// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MultiplicatorX3} from "../src/MultiplicatorX3.sol";

contract InvMutTest is Test {
    MultiplicatorX3 c;
    function setUp() public { c = new MultiplicatorX3(); }
    function testFuzz_property(address adr, uint256 amount, bytes calldata data) public {
        vm.assume(amount > 0);
        address owner = c.Owner();
        vm.deal(owner, amount);
        uint256 balanceBefore = address(adr).balance;
        vm.prank(owner);
        c.Command{value: amount}(adr, data);
        uint256 balanceAfter = address(adr).balance;
        assertTrue(balanceAfter == balanceBefore + amount);
    }
}
